/**
 * Data model for quorum-core.
 *
 * Conventions:
 * - All timestamps are epoch milliseconds (number): portable, serializable,
 *   no Date/timezone pitfalls across host stacks.
 * - IDs are opaque strings supplied by the host. The core never interprets them.
 * - Records are plain, JSON-serializable data so any storage adapter can persist them.
 */

/** Opaque ID of a user in the host system. */
export type UserId = string;
/** Opaque ID of a submission, generated by the host or storage adapter. */
export type SubmissionId = string;
/** Opaque ID of the thing being rated (e.g. a POI) in the host system. */
export type SubjectId = string;
/** Epoch milliseconds. */
export type Timestamp = number;

export type VoteChoice = "approve" | "reject";
export type Verdict = "approved" | "rejected";

/** Why a submission could not be decided by weight alone. */
export const REVIEW_REASONS = [
  "grey_zone",
  "weight_conflict",
  "sample",
  "extension_limit",
] as const;
export type ReviewReason = (typeof REVIEW_REASONS)[number];

/** Who made the final call. */
export type DecidedBy = "weight" | "review";

/** A user's reputation standing within one host site. */
export interface Reputation {
  userId: UserId;
  /** Raw reputation score. Stimmgewicht is derived from it, never stored here. */
  value: number;
  updatedAt: Timestamp;
}

/**
 * A single vote. `weight` is a snapshot taken when the vote was cast, so later
 * reputation changes (from other cases) cannot retroactively shift an open vote.
 */
export interface Vote {
  submissionId: SubmissionId;
  voterId: UserId;
  choice: VoteChoice;
  weight: number;
  castAt: Timestamp;
}

/** Final result of a submission. */
export interface Outcome {
  verdict: Verdict;
  decidedBy: DecidedBy;
  /** Weighted share of approvals at decision time (0..1); null if no weight was cast at all. */
  approvalRatio: number | null;
  /** Sum of all vote weights at decision time. */
  totalWeight: number;
  resolvedAt: Timestamp;
}

interface SubmissionBase {
  id: SubmissionId;
  authorId: UserId;
  /** What is being rated. Opaque to the core. */
  subjectId: SubjectId;
  /** Host-defined content of the submission. Opaque to the core. */
  payload?: unknown;
  createdAt: Timestamp;
  /** End of the current voting window. */
  windowEndsAt: Timestamp;
  /** Number of window extensions used so far. */
  extensions: number;
}

export interface OpenSubmission extends SubmissionBase {
  status: "open";
}

export interface ReviewSubmission extends SubmissionBase {
  status: "needs_review";
  reason: ReviewReason;
}

export interface ResolvedSubmission extends SubmissionBase {
  status: "resolved";
  outcome: Outcome;
}

/** Discriminated by `status`: a resolved submission always has an outcome, a review one always a reason. */
export type Submission = OpenSubmission | ReviewSubmission | ResolvedSubmission;
export type SubmissionStatus = Submission["status"];
